void rr_renderer_draw(const RViewport *vp, uint32_t flags, const RVertex *v, uint32_t nv, const uint32_t *idx, uint32_t ni) {
    if (rr_loop && rr_loop_on()) {
        RwWriter *rw_w = rr_start(RW_ID_DRAW, 0);
        if (rw_w) {
            rw_blob(rw_w, vp, vp ? sizeof(RViewport) : 0, vp != NULL, RW_CAT_ARGS);
            rw_u32(rw_w, flags);
            rw_blob(rw_w, v, v ? (size_t)nv * sizeof(RVertex) : 0, v != NULL, RW_CAT_VERTS);
            rw_u32(rw_w, nv);
            rw_blob(rw_w, idx, idx ? (size_t)ni * 4 : 0, idx != NULL, RW_CAT_INDICES);
            rw_u32(rw_w, ni);
            rr_finish(rw_w);
        }
        rr_loop_after(RW_ID_DRAW);
        return;
    }
    const double rr_t = rr_active ? rr_clock() : 0;
    renderer_draw(vp, flags, v, nv, idx, ni);
    if (rr_active) rr_call_time(RW_ID_DRAW, rr_t);
    RwWriter *rw_w = rr_active ? rr_start(RW_ID_DRAW, 0) : NULL;
    if (rw_w) {
        rw_blob(rw_w, vp, vp ? sizeof(RViewport) : 0, vp != NULL, RW_CAT_ARGS);
        rw_u32(rw_w, flags);
        rw_blob(rw_w, v, v ? (size_t)nv * sizeof(RVertex) : 0, v != NULL, RW_CAT_VERTS);
        rw_u32(rw_w, nv);
        rw_blob(rw_w, idx, idx ? (size_t)ni * 4 : 0, idx != NULL, RW_CAT_INDICES);
        rw_u32(rw_w, ni);
        rr_finish(rw_w);
    }
}
