int32_t rr_renderer_draw_skinned(const RViewport *vp, uint32_t flags, const RSkinJob *job, const uint32_t (*ins)[4], const float (*consts)[4], const uint8_t *data, uint32_t data_bytes, const uint32_t *idx, uint32_t ni, const RSkinNormals *nrm) {
    if (rr_loop && rr_loop_on()) {
        int32_t rr_ret = 0;
        const int rr_how = rr_loop_ask_renderer_draw_skinned(vp, flags, job, ins, consts, data, data_bytes, idx, ni, nrm, &rr_ret);
        if (rr_how != RR_LOOP_SKIP) {
            RwWriter *rw_w = rr_start(RW_ID_DRAW_SKINNED, 0);
            if (rw_w) {
                rw_blob(rw_w, vp, vp ? sizeof(RViewport) : 0, vp != NULL, RW_CAT_ARGS);
                rw_u32(rw_w, flags);
                rw_blob(rw_w, job, job ? sizeof(RSkinJob) : 0, job != NULL, RW_CAT_ARGS);
                rw_put_skin_prog(rw_w, ins, ins ? (size_t)job->nins * 16 : 0);
                rw_put_skin_consts(rw_w, consts);
                rw_blob(rw_w, data, data ? data_bytes : 0, data != NULL, RW_CAT_SKIN_DATA);
                rw_u32(rw_w, data_bytes);
                rw_blob(rw_w, idx, idx ? (size_t)ni * 4 : 0, idx != NULL, RW_CAT_INDICES);
                rw_u32(rw_w, ni);
                rw_put_skin_normals(rw_w, nrm, job->nv);
                rr_loop_result_at(rw_w);
                rw_i32(rw_w, rr_how == RR_LOOP_KNOWN ? rr_ret : 0);
                rr_finish(rw_w);
            }
            if (rr_how == RR_LOOP_WAIT) rr_ret = (int32_t)rr_loop_result(RW_ID_DRAW_SKINNED);
            else rr_loop_after(RW_ID_DRAW_SKINNED);
        }
        rr_loop_told_renderer_draw_skinned(vp, flags, job, ins, consts, data, data_bytes, idx, ni, nrm, rr_ret);
        return rr_ret;
    }
    const double rr_t = rr_active ? rr_clock() : 0;
    int32_t rr_ret = renderer_draw_skinned(vp, flags, job, ins, consts, data, data_bytes, idx, ni, nrm);
    if (rr_active) rr_call_time(RW_ID_DRAW_SKINNED, rr_t);
    RwWriter *rw_w = rr_active ? rr_start(RW_ID_DRAW_SKINNED, 0) : NULL;
    if (rw_w) {
        rw_blob(rw_w, vp, vp ? sizeof(RViewport) : 0, vp != NULL, RW_CAT_ARGS);
        rw_u32(rw_w, flags);
        rw_blob(rw_w, job, job ? sizeof(RSkinJob) : 0, job != NULL, RW_CAT_ARGS);
        rw_put_skin_prog(rw_w, ins, ins ? (size_t)job->nins * 16 : 0);
        rw_put_skin_consts(rw_w, consts);
        rw_blob(rw_w, data, data ? data_bytes : 0, data != NULL, RW_CAT_SKIN_DATA);
        rw_u32(rw_w, data_bytes);
        rw_blob(rw_w, idx, idx ? (size_t)ni * 4 : 0, idx != NULL, RW_CAT_INDICES);
        rw_u32(rw_w, ni);
        rw_put_skin_normals(rw_w, nrm, job->nv);
        rw_i32(rw_w, rr_ret);
        rr_finish(rw_w);
    }
    return rr_ret;
}
